class DiscWrapper(nn.Module):
    def __init__(self, cfg, disc, update_freq=2, percept=None):
        super().__init__()
        self.disc = disc
        self.percept = percept
        self.use_percept = False
        self.record_data = True
        self.cfg = cfg
